#pragma once
// CartoRig Fusion RC1 — original geographic runtime (C++20, no network).
// CRG1 binary schema is generated by tools/build_ne.py.
// Data from Natural Earth; polygons/points represent only published features.
#include <cstdint>
#include <filesystem>
#include <string>
#include <unordered_map>
#include <vector>

namespace cartorig::rc1 {

struct GeoPoint { double lon=0,lat=0; };
struct ScreenPoint { double x=0,y=0; };
struct Bounds {double west=0,south=0,east=0,north=0;};
struct Color {uint8_t r=0,g=0,b=0,a=255;};
struct Camera {
  GeoPoint center{0,0}; double zoom=1,bearing=0;
  void validate() const;
};
struct Geometry {
  std::string id,kind;
  Bounds bounds;
  uint8_t shape=0;
  std::vector<uint32_t> parts;
  std::vector<GeoPoint> points;
};
struct Location {
  std::string id,kind,name,parent,aliases;
  Bounds bounds;
  uint64_t offset=0,length=0;
};
class Catalog {
public:
  explicit Catalog(const std::filesystem::path& directory);
  std::vector<Location> search(const std::string& text,const std::string& kind="all",
                               std::size_t limit=50) const;
  Geometry geometry(const std::string& id) const;
  std::vector<Location> all(const std::string& kind) const;
  std::size_t size() const {return records_.size();}
private:
  std::filesystem::path archive_;
  std::vector<Location> records_;
  std::unordered_map<std::string,std::size_t> byId_;
};

ScreenPoint project(GeoPoint point,const Camera& camera,int width,int height);
double shortestLongitude(double from,double to);
Camera fit(const Bounds& bounds,int width,int height,double padding=0.08);

struct Surface {
  int width=0,height=0;
  std::vector<uint8_t> rgba;
  explicit Surface(int w,int h);
  void clear(Color color);
  void blend(int x,int y,Color color,double alpha=1.0);
  Color pixel(int x,int y) const;
};
struct RouteOptions {
  GeoPoint from,to;
  std::vector<GeoPoint> waypoints; // ordered authoring points, max 64
  bool curved=false;             // Straight is baseline
  double curvature=0;      // -100...100; no implied road routing
  double width=3;          // screen pixels
  double progress=1;       // draw progress, 0...1
  double trimStart=0,trimEnd=1;
  bool arrowhead=false,reverseArrowhead=false;
  double arrowheadSize=12;
  double followerProgress=0; // optional linked marker controller
  Color stroke{214,223,230,255};
  double opacity=1;
};
struct MarkerOptions {
  GeoPoint at;
  double size=14,strokeWidth=1.5;
  double offsetX=0,offsetY=0;
  bool ring=false;
  Color fill{224,232,237,255},stroke{20,38,55,255};
  double opacity=1;
};
struct RegionStyle {
 Color fill{130,150,164,255},stroke{215,224,231,255};
 Color highlight{230,198,107,255};
 double fillAlpha=1,strokeAlpha=1,objectOpacity=1;
 double strokeWidth=1.5,strokeProgress=1,highlightStrength=0;
 bool strokeVisible=true,highlightStroke=false,outerContoursOnly=false;
};
void drawRegion(Surface& canvas,const Geometry& geom,const Camera& camera,
                const RegionStyle& style);
void drawGeometry(Surface& canvas,const Geometry& geom,const Camera& camera,
                  Color fill,Color stroke,double strokeWidth=1.5,
                  double opacity=1);
void drawRoute(Surface& canvas,const Camera& camera,const RouteOptions& route);
void drawMarker(Surface& canvas,const Camera& camera,const MarkerOptions& marker);
std::string normalizedQuery(const std::string& input);

} // namespace cartorig::rc1
